import sys
import json
import urllib.request
import urllib.parse
import re


def main():
    if len(sys.argv) < 2:
        return
    query = sys.argv[1].strip()

    safe_query = urllib.parse.quote(query)
    url_translate = f"https://translate.googleapis.com/translate_a/single?client=dict-chrome-ex&sl=en&tl=sv&dt=t&q={safe_query}"


    translated_word = ""
    try:
        req = urllib.request.Request(url_translate, headers={'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36',

    'Accept-Language': 'en-US,en;q=0.9',

    'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,image/webp,*/*;q=0.8'})
        with urllib.request.urlopen(req) as response:
            data = json.loads(response.read().decode('utf-8'))
            if data and data[0] and data[0][0]:
                translated_word = data[0][0][0]
    except Exception as e:
        print(json.dumps({"items": [{"title": "Översättningsfel (Google)", "subtitle": str(e)}] }))
        return

    if not translated_word:
        print(json.dumps({"items": [{"title": "Kunde inte översätta", "valid": False}] }))
        return

    safe_translated = urllib.parse.quote(translated_word.lower())
    url_synonyms = f"https://www.synonymer.se/sv-syn/{safe_translated}"

    synonyms = []
    try:
        req = urllib.request.Request(url_synonyms, headers={'User-Agent': 'Mozilla/5.0'})
        with urllib.request.urlopen(req) as response:
            html = response.read().decode('utf-8')

            matches = re.findall(r'<a[^>]*href="/sv-syn/[^>]*>([^<]+)</a>', html)

            if matches:
                for m in matches:
                    clean_m = m.strip()
                    if clean_m.lower() != translated_word.lower() and clean_m not in synonyms:
                        synonyms.append(clean_m)
                synonyms = synonyms[:5]
    except urllib.error.HTTPError:
        pass
    except Exception as e:
        pass

    items = []

    items.append({
        "title": translated_word,
        "subtitle": f"Översättning av '{query}'",
        "arg": translated_word,
        "valid": True
    })

    for syn in synonyms:
        items.append({
            "title": syn,
            "subtitle": f"Synonym till {translated_word}",
            "arg": syn,
            "valid": True
        })

    if len(items) == 1:
        items.append({
            "title": "Inga synonymer hittades",
            "subtitle": "Kunde inte hitta synonymer på synonymer.se",
            "valid": False
        })

    print(json.dumps({"items": items}))


if __name__ == '__main__':
    main()
